     *
     * @param string $dec_id
     * @param string $key_id
     * @return static|null
     */
    public static function find(string $dec_id, string $key_id): ?static
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM INCLURE WHERE DEC_ID = ? AND KEY_ID = ? LIMIT 1');
        $stmt->execute([$dec_id, $key_id]);
        $row = $stmt->fetch();

        return $row ? (new static())->hydrate($row) : null;
    }

    /**
     * Récupère tous les enregistrements de la table.
     *
     * @return static[]
     */
    public static function findAll(): array
    {
        $stmt = Database::getInstance()->query('SELECT * FROM INCLURE');
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
     * Récupère les instances Inclure associées à un objet Decision.
     *
     * @param Decision $source
     * @return static[]
     */
    public static function getFromDecision(Decision $source): array
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM INCLURE WHERE DEC_ID = ?');
        $stmt->execute([$source->DEC_ID]);
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
